/**
 * GitHub Node - Version 1
 * Discriminator: resource=pullRequest, operation=merge
 */


interface Credentials {
  githubApi: CredentialReference;
  githubOAuth2Api: CredentialReference;
  githubAppApi: CredentialReference;
}

/** Merge a pull request */
export type GithubV1PullRequestMergeParams = {
  resource: 'pullRequest';
  operation: 'merge';
  authentication?: 'accessToken' | 'oAuth2' | 'githubAppApi' | Expression<string>;
/**
 * The number of the pull request
 * @default 0
 */
    pullRequestNumber?: number | Expression<number>;
/**
 * Merge Method
 * @default merge
 */
    mergeMethod?: 'merge' | 'squash' | 'rebase' | Expression<string>;
/**
 * Title for the automatic merge commit
 */
    commitTitle?: string | Expression<string>;
/**
 * Extra detail to append to automatic merge commit
 */
    commitMessage?: string | Expression<string>;
/**
 * Repository Owner
 * @searchListMethod getUsers
 * @displayOptions.hide { operation: ["invite", "getUserIssues"] }
 * @default {"mode":"list","value":""}
 */
    owner?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * Repository Name
 * @searchListMethod getRepositories
 * @displayOptions.hide { resource: ["user", "organization"], operation: ["getRepositories"] }
 * @default {"mode":"list","value":""}
 */
    repository?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
};

export type GithubV1PullRequestMergeNode = {
  type: 'n8n-nodes-base.github';
  version: 1;
  config: NodeConfig<GithubV1PullRequestMergeParams> & { credentials?: Credentials };
};